"""Shared control resolution for the seven-layer Push surface."""
import ast
import math
import re
import time


def _decode_relative(v):
    v = int(v)
    return v if 1 <= v <= 63 else v - 128 if 65 <= v <= 127 else 0


def _expression(expression, context):
    def read(n):
        if isinstance(n, ast.Constant) and isinstance(n.value, (int, float)):
            return n.value
        if isinstance(n, ast.Name) and n.id in context:
            return context[n.id]
        if isinstance(n, ast.BinOp) and isinstance(n.op, (ast.Add, ast.Sub, ast.Mult)):
            a, b = read(n.left), read(n.right)
            return a + b if isinstance(n.op, ast.Add) else a - b if isinstance(n.op, ast.Sub) else a * b
        raise ValueError('Unsupported mapping expression: ' + str(expression))
    return read(ast.parse(str(expression), mode='eval').body)


class Surface:
    def __init__(self, ownerComp):
        self.ownerComp = ownerComp
        self.GridMode, self.EncoderPage = 'SESSION', 'OPACITY'
        self.Bank, self.FxPage = 1, 1
        self.FocusTarget = self.LastLayerTarget = 'LAYER1'
        self.HeldFocusTarget = None
        self.Modifiers = set()
        self.EncoderValues, self.EncoderWritten = {}, {}
        self.ClipScrollX = 0.0
        self._index, self._cfg = {}, {}
        self.LoadCfg()
        self.BuildIndex()

    def LoadCfg(self):
        t = self.ownerComp.op('config/cfg_general')
        self._cfg = {t[r, 'key'].val: t[r, 'value'].val for r in range(1, t.numRows)}
        return self._cfg

    def Cfg(self, key, default=None, cast=str):
        v = self._cfg.get(key)
        return cast(v) if v is not None else default

    def BuildIndex(self):
        t = self.ownerComp.op('config/map_controls')
        columns = [t[0, c].val for c in range(t.numCols)]
        self._index = {}
        for r in range(1, t.numRows):
            row = {c: t[r, c].val for c in columns}
            self._index[(row['in_type'], int(row['in_number']), row['modifier'], row['grid_mode'])] = row
        return len(self._index)

    def LayerIds(self):
        return [p.strip() for p in self.Cfg('layer_ids', '1,2,3,4,5,6,7').split(',') if p.strip()]

    def Targets(self):
        return ['LAYER%d' % i for i in range(1, len(self.LayerIds()) + 1)] + ['COMPOSITION']

    def LayerFor(self, target):
        m = re.fullmatch(r'LAYER(\d+)', target or '')
        i = int(m[1]) - 1 if m else -1
        ids = self.LayerIds()
        return ids[i] if 0 <= i < len(ids) else None

    def Context(self):
        return dict({'L%d' % i: int(v) for i, v in enumerate(self.LayerIds(), 1)},
                    bank=self.Bank - 1, fx_page=self.FxPage - 1, bank_group=((self.Bank - 1) // 8) * 8)

    def Slot(self, row):
        return int(_expression(row['slot'], self.Context())) if row.get('slot') else None

    def BankCount(self):
        state = self.ownerComp.ResolumeState
        columns = len((state.Composition or {}).get('columns', [])) if state else 0
        return max(self.Cfg('bank_count', 16, int), math.ceil(columns / self.Cfg('clips_per_bank', 8, int)))

    def FxPageCount(self):
        return math.ceil(self.Cfg('fx_slots_per_target', 16, int) / self.Cfg('fx_visible_slots', 8, int))

    def SetBank(self, bank):
        self.Bank = max(1, min(self.BankCount(), int(bank)))

    def SetGridMode(self, mode):
        if mode in ('SESSION', 'FX'):
            self.GridMode = mode

    def ActiveModifier(self):
        return 'SELECT' if 'SELECT' in self.Modifiers else 'SHIFT' if 'SHIFT' in self.Modifiers else ''

    def Resolve(self, in_type, number, modifier, grid_mode):
        encoder = in_type == 'cc' and 71 <= number <= 78
        lookup = '' if encoder and modifier == 'SELECT' else modifier
        for mod in ([lookup, ''] if lookup else ['']):
            for mode in (grid_mode, 'ANY'):
                row = self._index.get((in_type, int(number), mod, mode))
                if row is not None:
                    row = dict(row)
                    if encoder and grid_mode == 'SESSION' and self.EncoderPage == 'MACRO':
                        prefix = '/composition' + ('' if row['target'] == 'COMPOSITION' else '/layers/{L%d}' % (number - 70))
                        row['control_path'] = prefix + '/dashboard/link%d' % (2 if lookup == 'SHIFT' else 1)
                    return row
        return None

    def ResolveTemplate(self, control_path, target='', slot_expr='', fx_registry=None, focus_override=None):
        if not control_path:
            return ''
        ctx = self.Context()
        focus = focus_override or self.FocusTarget
        if focus not in self.Targets():
            raise ValueError('Unknown focus target: ' + str(focus))
        ctx['FOCUS'] = '' if focus == 'COMPOSITION' else '/layers/' + self.LayerFor(focus)
        ctx['LAST_LAYER'] = self.LayerFor(self.LastLayerTarget)
        ctx['ACTIVE_CLIP'] = self.ownerComp.ResolumeState.ActiveClip(target) or 0 if self.ownerComp.ResolumeState else 0
        if slot_expr:
            ctx['slot'] = _expression(slot_expr, ctx)
        def replace(m):
            token = m[1]
            fx = re.fullmatch(r'fx\[([A-Z0-9]+):([^\]]+)\]\.([a-z_]+)', token)
            if fx:
                entry = fx_registry.Registry.get('%s:%d' % (fx[1], int(_expression(fx[2], ctx)))) if fx_registry else None
                value = entry.get(fx[3]) if entry else None
                if value is None:
                    raise ValueError('FX slot unavailable')
                return str(value)
            return str(ctx[token] if token in ctx else _expression(token, ctx))
        return re.sub(r'\{([^{}]+)\}', replace, control_path)

    def Available(self, row):
        action = row['action']
        state = self.ownerComp.ResolumeState
        if action == 'reserved':
            return False
        if action == 'speed_reset':
            path = self.ResolveTemplate(row['control_path'], row['target'])
            meta = state.ParameterMeta.get(path, {}) if state else {}
            lo, hi = meta.get('min'), meta.get('max')
            return isinstance(lo, (int,float)) and isinstance(hi, (int,float)) and lo <= 1.0 <= hi and hi > lo
        if action == 'param_relative' and '{ACTIVE_CLIP}' in row['control_path']:
            index = state.ActiveClip(row['target']) if state else None
            clip = state.Clips.get((self.LayerFor(row['target']), index), {}) if state else {}
            return bool(clip.get('speed') is not None)
        if action in ('clip_connect', 'clip_select'):
            clip = state.Clips.get((self.LayerFor(row['target']), self.Slot(row))) if state else None
            return bool(clip and clip.get('present'))
        if action == 'column_connect':
            return bool(state and any(c.get('present') for (lid, ci), c in state.Clips.items() if ci == self.Slot(row)))
        if action in ('fx_opacity_toggle', 'fx_bypass_toggle', 'fx_capture_on_value'):
            registry = self.ownerComp.FxRegistry
            entry = registry.Registry.get('%s:%d' % (row['target'], self.Slot(row))) if registry else None
            return bool(entry and entry.get('bypassed_id' if action == 'fx_bypass_toggle' else 'opacity_id'))
        if action == 'fx_page_select':
            return self.Slot(row) <= self.FxPageCount()
        if action == 'clip_bank_select':
            return self.Slot(row) <= self.BankCount()
        if action == 'deck_select':
            return bool(state and self.Slot(row) <= len((state.Composition or {}).get('decks', [])))
        return True

    def ParameterValue(self, row):
        path = self.ResolveTemplate(row['control_path'], row['target'], row['slot'], self.ownerComp.FxRegistry)
        live = self.ownerComp.ResolumeState.Value(path) if self.ownerComp.ResolumeState else None
        if path in self.EncoderValues and time.monotonic() - self.EncoderWritten.get(path, 0) < 0.4:
            return self.EncoderValues[path]
        return float(live) if live is not None else self.EncoderValues.get(path, 0.1 if path.endswith('/speed') else 0.0)

    def LogDryRun(self, row, path, value):
        log = self.ownerComp.op('logic/dryrun_log')
        line = '%s action=%s transport=%s path=%s type=%s value=%s' % (row['id'], row['action'], row['transport'], path, row['value_type'], value)
        if log is not None:
            log.text = '\n'.join((log.text.splitlines() + [line])[-500:])

    def HandleInternal(self, row, value, ext):
        action = row['action']
        if action in ('modifier_shift', 'modifier_select'):
            mod = 'SHIFT' if action == 'modifier_shift' else 'SELECT'
            (self.Modifiers.add if value else self.Modifiers.discard)(mod)
            return
        if not value:
            return
        if action == 'grid_mode_toggle':
            self.SetGridMode('FX' if self.GridMode == 'SESSION' else 'SESSION')
        elif action == 'encoder_page_toggle':
            self.EncoderPage = 'MACRO' if self.EncoderPage == 'OPACITY' else 'OPACITY'
        elif action in ('clip_bank_prev', 'clip_bank_next'):
            self.SetBank(self.Bank + (1 if action.endswith('next') else -1))
        elif action == 'clip_bank_select':
            self.SetBank(self.Slot(row))
        elif action in ('fx_page_prev', 'fx_page_next'):
            self.FxPage = max(1, min(self.FxPageCount(), self.FxPage + (1 if action.endswith('next') else -1)))
        elif action == 'fx_page_select':
            self.FxPage = self.Slot(row)
        elif action == 'surface_panic':
            ext.Panic()
        elif action == 'surface_resync':
            ext.Resync()
        elif action == 'fx_registry_rescan':
            ext.ResolumeState.Rebind()
            ext.FxRegistry.Rescan()
        elif action == 'push_mode_toggle':
            ext.PushIO.SetMode('live' if ext.PushIO.PushMode else 'user')
        elif action == 'ui_toggle':
            panel = self.ownerComp.op('ui')
            panel.par.display = int(not panel.par.display.eval())
        elif action in ('display_toggle', 'display_fit_toggle', 'display_source_toggle') and ext.Display:
            getattr(ext.Display, {'display_toggle': 'ToggleMode', 'display_fit_toggle': 'ToggleFit', 'display_source_toggle': 'ToggleSource'}[action])()

    def OnReceiveMIDI(self, in_type, number, channel, value, ext):
        row = self.Resolve(in_type, number, self.ActiveModifier(), self.GridMode)
        if row is None or row['action'] == 'reserved':
            return row
        action = row['action']
        if in_type == 'cc' and 20 <= number <= 27 and not value:
            if self.HeldFocusTarget == self.Targets()[number-20]:
                self.HeldFocusTarget = None
            return row
        if action in ('layer_focus', 'comp_focus') and not value:
            if self.HeldFocusTarget == row['target']:
                self.HeldFocusTarget = None
            return row
        if row['transport'] == 'internal' and action != 'fx_capture_on_value':
            if self.Available(row):
                self.HandleInternal(row, value, ext)
            return row
        if action != 'param_absolute' and not value:
            return row
        if not ext.Armed or not self.Available(row):
            return row
        if action in ('fx_opacity_toggle', 'fx_bypass_toggle', 'fx_capture_on_value'):
            slot = self.Slot(row)
            if action == 'fx_opacity_toggle':
                ext.FxRegistry.TogglePad(row['target'], slot, ext.ResolumeOut)
            elif action == 'fx_bypass_toggle':
                ext.FxRegistry.ToggleBypass(row['target'], slot, ext.ResolumeOut)
            else:
                current = ext.ResolumeState.CurrentOpacity(row['target'], slot)
                if current is not None:
                    if self.Cfg('dry_run', '0') == '1':
                        self.LogDryRun(row, row['control_path'], current)
                    else:
                        ext.FxRegistry.SetOnValue(row['target'], slot, current)
            return row
        if action in ('layer_focus', 'comp_focus'):
            self.FocusTarget = self.HeldFocusTarget = row['target']
            if self.LayerFor(row['target']):
                self.LastLayerTarget = row['target']
        if action == 'comp_bypass_toggle' and self.HeldFocusTarget:
            path = self.ResolveTemplate('/composition{FOCUS}/bypassed', focus_override=self.HeldFocusTarget)
        else:
            path = self.ResolveTemplate(row['control_path'], row['target'], row['slot'], ext.FxRegistry)
        if action == 'speed_reset':
            meta = ext.ResolumeState.ParameterMeta[path]
            output = (1.0 - meta['min']) / (meta['max'] - meta['min'])
        elif action == 'param_relative':
            scale = self.Cfg('encoder_fine_scale', 0.2, float) if 'SELECT' in self.Modifiers else 1.0
            output = max(0.0, min(1.0, self.ParameterValue(row) + _decode_relative(value) * self.Cfg('encoder_step', 0.005, float) * scale))
            self.EncoderValues[path], self.EncoderWritten[path] = output, time.monotonic()
        elif action == 'param_absolute':
            output = value / 16383.0
        elif action in ('clip_scroll_prev', 'clip_scroll_next'):
            self.ClipScrollX = max(0.0, min(1.0, self.ClipScrollX + (0.1 if action.endswith('next') else -0.1)))
            output = self.ClipScrollX
        elif row['value'] == '0|1':
            output = int(not bool(ext.ResolumeState.Value(path)))
        else:
            output = float(row['value'])
        deck_change = action in ('deck_select', 'deck_prev', 'deck_next')
        if deck_change:
            ext.ResolumeOut.ClearPending()
        sent = ext.ResolumeOut.Send(row, path, output)
        if action == 'speed_reset' and sent:
            self.EncoderValues[path], self.EncoderWritten[path] = output, time.monotonic()
            clip = ext.ResolumeState.Clips.get((self.LayerFor(row['target']), ext.ResolumeState.ActiveClip(row['target'])))
            if clip is not None:
                clip['speed'] = 1.0
        if self.Cfg('dry_run', '0') != '1':
            ext.ResolumeState.Optimistic(path, output)
            if deck_change:
                ext.ResolumeState.Clips.clear()
                run('args[0].FxRegistry.Rescan()', self.ownerComp, delayFrames=15)
        return row

sources.logic/mod_resolume_out:
"""ResolumeOut: the single write path for both transports. OSC half is live
(Phase 3); the WS half is a queueing stub until FxRegistry exists (Phase 4).
See DESIGN.md 2.3, 6."""

import json
import time

def _cast(value_type, value):
	if value_type == 'int':
		return int(round(float(value)))
	if value_type == 'bool_as_int':
		return int(bool(value) and value != 0)
	if value_type == 'float':
		return float(value)
	return value


class ResolumeOut:
	def __init__(self, ownerComp):
		self.ownerComp = ownerComp
		self.oscOut = ownerComp.op('net/oscout1')
		self.wsOut = ownerComp.op('net/ws1')
		self._oscCache = {}
		self._oscPending = {}
		self._oscQueue = []
		self._oscQueued = set()
		self._wsPending = {}
		self._wsQueue = []
		self._wsQueued = set()
		self._wsReadbacks = {}

	def Cfg(self, key, default=None, cast=str):
		t = self.ownerComp.op('config/cfg_general')
		for r in range(1, t.numRows):
			if t[r, 'key'].val == key:
				return cast(t[r, 'value'].val)
		return default

	def Send(self, row, resolved_path, value):
		"""Enqueue one control write. Called from Surface.OnReceiveMIDI. The
		actual dead-band diff and send happen at flush time (FlushOSC/FlushWS),
		so a burst of the same path in one tick coalesces to one message."""
		if not self.ownerComp.Armed:
			return False
		if '{' in resolved_path or not resolved_path.startswith('/'):
			raise ValueError('Unresolved control path: ' + resolved_path)
		if self.Cfg('dry_run', '0') == '1':
			self.ownerComp.Surface.LogDryRun(row, resolved_path, value)
			return False
		typed = _cast(row['value_type'], value)
		if row['transport'] == 'osc':
			self._enqueue(self._oscQueue, self._oscQueued, self._oscPending,
			              resolved_path, (typed, row['value_type']))
		elif row['transport'] == 'ws':
			self._enqueue(self._wsQueue, self._wsQueued, self._wsPending,
			              resolved_path, (typed, row['value_type']))
		# 'internal' transport is handled entirely by Surface.HandleInternal.
		return True

	def ClearPending(self, ws_only=False):
		self._wsReadbacks.clear()
		for prefix in (('_ws',) if ws_only else ('_ws', '_osc')):
			getattr(self, prefix + 'Queue').clear()
			getattr(self, prefix + 'Queued').clear()
			getattr(self, prefix + 'Pending').clear()
		if not ws_only:
			self._oscCache.clear()

	@staticmethod
	def _enqueue(queue, queued, pending, key, item):
		if key not in queued:
			queue.append(key)
			queued.add(key)
		pending[key] = item

	def FlushOSC(self, cap=32):
		if not self.ownerComp.Armed or self.Cfg('dry_run', '0') == '1':
			self.ClearPending()
			return 0
		deadband = self.Cfg('osc_deadband', 0.002, float)
		sent = 0
		while self._oscQueue and sent < cap:
			path = self._oscQueue.pop(0)
			self._oscQueued.discard(path)
			item = self._oscPending.pop(path, None)
			if item is None:
				continue
			value, value_type = item
			cached = self._oscCache.get(path)
			# Dead-band is for CONTINUOUS float streams only (encoders/touch
			# strip) -- DESIGN.md 6. Discrete int/bool triggers (clip_connect,
			# layer_focus, column_connect...) must always re-send even when
			# the value is unchanged: every physical press is a fresh bang,
			# not a state stream. An earlier version of this check also
			# skipped unchanged ints, which silently ate every repeat press
			# of any trigger whose CSV value is a constant (e.g. always 1).
			if value_type == 'float' and cached is not None and abs(value - cached) < deadband:
				continue
			self.oscOut.sendOSC(path, [value], asBundle=True, useNonStandardTypes=False)
			self._oscCache[path] = value
			sent += 1
		return sent

	def FlushWS(self, cap=16):
		"""WS half. Envelope confirmed live against Resolume Arena --
		see PHASE3A_FINDINGS.md 6: {"action":"set","parameter":<path str>,"value":<v>}.
		Any path still containing 'fx[' means FxRegistry has not resolved it
		yet (unknown slot) and is dropped."""
		if not self.ownerComp.Armed or self.Cfg('dry_run', '0') == '1':
			self.ClearPending()
			return 0
		sent = 0
		while self._wsQueue and sent < cap:
			path = self._wsQueue.pop(0)
			self._wsQueued.discard(path)
			item = self._wsPending.pop(path, None)
			if item is None or 'fx[' in path:
				continue
			value, value_type = item
			self._sendWS(path, value)
			self._wsReadbacks[path] = time.monotonic() + 0.05
			sent += 1
		# Read on a later Resolume frame, not from its pre-write set reply.
		now = time.monotonic()
		for path, due in list(self._wsReadbacks.items()):
			if sent >= cap:
				break
			if due <= now:
				self.wsOut.sendText(json.dumps({'action':'get', 'parameter':path}))
				self._wsReadbacks.pop(path, None)
				sent += 1
		return sent

	def _sendWS(self, path, value):
		self.wsOut.sendText(json.dumps({'action': 'set', 'parameter': path, 'value': value}))

	def SendWSById(self, param_id, value):
		row = {'id': 'FX_' + str(param_id), 'action': 'fx_set', 'transport': 'ws',
		       'value_type': 'bool_as_int' if isinstance(value, bool) else 'float'}
		return self.Send(row, '/parameter/by-id/%s' % param_id, value)

sources.logic/mod_resolume_state:
"""Normalize API state and keep explicit layer identity bindings."""
import json
import re
import time


def normalized(parameter):
    value = parameter.get('value')
    if parameter.get('valuetype') == 'ParamRange' and isinstance(value, (int, float)):
        lo, hi = parameter.get('min', 0), parameter.get('max', 1)
        return (value - lo) / (hi - lo) if hi != lo else 0.0
    return value


class ResolumeState:
    def __init__(self, ownerComp):
        self.ownerComp = ownerComp
        self.Composition = None
        self.Connected = False
        self.LastReceived = 0.0
        self.Clips, self.Layers = {}, {}
        self.DashboardLinks, self.DashboardLinkNames = {}, {}
        self.Parameters, self.ParameterIds, self.TargetNames = {}, {}, {}
        self.ParameterMeta = {}
        self.Pending = {}
        self.PollPending = False
        self.LatestRequest = None
        self.Syncing = False
        self.SyncError = ''
        self.Bindings = dict(ownerComp.fetch('layout7_bindings', {}, search=False))
        self.BindingError = ''

    def LayerIds(self):
        return self.ownerComp.Surface.LayerIds()

    def IsCompositionMessage(self, msg):
        return isinstance(msg, dict) and 'layers' in msg and 'columns' in msg

    def Rebind(self):
        self.Bindings = {}
        self.ownerComp.store('layout7_bindings', {})
        self.BindingError = ''
        self.Pending.clear()
        self.ownerComp.Surface.EncoderValues.clear()
        self.ownerComp.ResolumeOut.ClearPending()

    def Request(self, ext):
        self.PollPending = True
        try:
            self.LatestRequest = self.ownerComp.op('net/web1').request(
                'http://%s:%d/api/v1/composition' % (
                    ext.PushIO.Cfg('resolume_ip', '127.0.0.1'),
                    ext.PushIO.Cfg('resolume_web_port', 8080, int)), 'GET', timeout=8000)
        except Exception as error:
            self.PollPending = False
            if self.Syncing:
                ext.FinishResync(str(error))

    def OnResponse(self, data, request_id, ext, error=''):
        if request_id != self.LatestRequest:
            return
        self.PollPending = False
        success = False
        if not error:
            try:
                success = self.OnMessage(data.decode('utf-8'), ext, authoritative=True)
            except UnicodeError as decode_error:
                error = str(decode_error)
        if self.Syncing:
            ext.FinishResync('' if success else error or self.BindingError or 'Invalid composition response')

    def OnMessage(self, text, ext, authoritative=False):
        if self.Syncing and not authoritative:
            return False
        try:
            msg = json.loads(text)
        except (ValueError, TypeError):
            return False
        if self.IsCompositionMessage(msg):
            self.Composition = msg
            try:
                self._normaliseFromComposition(msg)
                if self.LayerIdsOK() and ext.FxRegistry:
                    ext.FxRegistry.Rebuild(msg)
                elif ext.ResolumeOut:
                    ext.ResolumeOut.ClearPending()
            except (AttributeError, TypeError, ValueError, KeyError) as error:
                self.BindingError = 'Invalid composition state: ' + str(error)
                self.LastReceived = 0.0
                return False
            self.LastReceived = time.monotonic()
            self.SyncError = ''
            return self.LayerIdsOK()
        # Set replies can contain the pre-write value, not authoritative state.
        elif isinstance(msg, dict) and msg.get('type') in ('parameter_update','parameter_get'):
            self._applyParameterUpdate(msg)

    def _walk(self, value, path):
        if not isinstance(value, dict):
            return
        if 'valuetype' in value:
            self.Parameters[path] = normalized(value)
            self.ParameterMeta[path] = value
            if 'id' in value:
                self.ParameterIds[str(value['id'])] = (path, value)
            return
        for key, child in value.items():
            if key in ('layers', 'columns', 'decks', 'clips', 'effects'):
                continue
            part = 'link' + key[5:] if key.startswith('Link ') else key
            self._walk(child, path + '/' + part.lower())

    def _normaliseFromComposition(self, comp):
        self.Clips, self.Layers = {}, {}
        self.Parameters, self.ParameterIds = {}, {}
        self.ParameterMeta = {}
        self.DashboardLinks, self.DashboardLinkNames, self.TargetNames = {}, {}, {}
        self._walk(comp, '/composition')
        self._extractDashboard('COMPOSITION', comp.get('dashboard', {}))
        self.TargetNames['COMPOSITION'] = 'Composition'
        self.BindingError = ''
        try:
            ids = [int(v) for v in self.LayerIds()]
        except ValueError:
            self.BindingError = 'Layer indices must be integers'
            return
        layers = comp.get('layers', [])
        if len(ids) != 7 or len(set(ids)) != len(ids) or any(i < 1 or i > len(layers) for i in ids):
            self.BindingError = 'Seven distinct existing layer indices required'
            return
        actual = {str(index): layers[index - 1].get('id') for index in ids}
        if self.Bindings and self.Bindings != actual:
            self.BindingError = 'Layer identities changed; Shift+Stop to rebind'
        elif not self.Bindings:
            self.Bindings = actual
            self.ownerComp.store('layout7_bindings', actual)
        for pos, index in enumerate(ids, 1):
            layer = layers[index - 1]
            lid, target = str(index), 'LAYER%d' % pos
            self.TargetNames[target] = layer.get('name', {}).get('value', target)
            self.Layers[lid] = {key: layer.get(key, {}).get('value') for key in ('bypassed', 'solo', 'ignorecolumntrigger')}
            self.Layers[lid]['opacity'] = layer.get('video', {}).get('opacity', {}).get('value')
            self._walk(layer, '/composition/layers/' + lid)
            self._extractDashboard(target, layer.get('dashboard', {}))
            for ci, clip in enumerate(layer.get('clips', []), 1):
                state = clip.get('connected', {}).get('value')
                speed = ((clip.get('transport') or {}).get('controls') or {}).get('speed')
                if speed:
                    self._walk(speed, '/composition/layers/%s/clips/%d/transport/position/behaviour/speed' % (lid, ci))
                self.Clips[(lid, ci)] = {'connected': state in ('Connected', 'Connected & previewing'),
                    'present': state is not None and state != 'Empty', 'state': state,
                    'name': clip.get('name', {}).get('value', ''), 'id': clip.get('id'),
                    'speed':speed.get('value') if speed else None}
        for path, (value, until) in list(self.Pending.items()):
            if time.monotonic() >= until:
                self.Pending.pop(path, None)
            else:
                self._applyOptimistic(path, value)

    def _extractDashboard(self, target, dashboard):
        for i in range(1, 9):
            link = dashboard.get('Link %d' % i)
            if link:
                self.DashboardLinks[(target, i)] = normalized(link)
                self.DashboardLinkNames[(target, i)] = link.get('view', {}).get('alternative_name', '')

    def DashboardLinkValue(self, target, index):
        return self.DashboardLinks.get((target, index))

    def DashboardLinkName(self, target, index):
        return self.DashboardLinkNames.get((target, index))

    def Value(self, path):
        return self.Parameters.get(path)

    def ActiveClip(self, target):
        lid = self.ownerComp.Surface.LayerFor(target)
        return next((ci for (layer, ci), clip in self.Clips.items() if layer == lid and clip.get('connected')), None)

    def NativeValue(self, path, value):
        p = self.ParameterMeta.get(path, {})
        return p.get('min', 0) + value * (p.get('max', 1)-p.get('min', 0))

    def Optimistic(self, path, value):
        self.Pending[path] = (value, time.monotonic() + 0.5)
        self._applyOptimistic(path, value)

    def _applyOptimistic(self, path, value):
        self.Parameters[path] = value
        clip = re.fullmatch(r'/composition/layers/(\d+)/clips/(\d+)/connect', path)
        column = re.fullmatch(r'/composition/columns/(\d+)/connect', path)
        clear = re.fullmatch(r'/composition/layers/(\d+)/clear', path)
        if clip or column or clear or path == '/composition/disconnectall':
            layer = clip[1] if clip else clear[1] if clear else None
            index = int(clip[2] if clip else column[1]) if clip or column else None
            for (lid, ci), entry in self.Clips.items():
                if layer and lid != layer:
                    continue
                if column and (self.Layers.get(lid, {}).get('ignorecolumntrigger') or not self.Clips.get((lid, index), {}).get('present')):
                    continue
                entry['connected'] = bool(index == ci and entry['present'])
        link = re.fullmatch(r'/composition(?:/layers/(\d+))?/dashboard/link(\d+)', path)
        if link:
            target = 'COMPOSITION' if link[1] is None else next((t for t in self.ownerComp.Surface.Targets() if self.ownerComp.Surface.LayerFor(t) == link[1]), None)
            if target:
                self.DashboardLinks[(target, int(link[2]))] = value

    def _applyParameterUpdate(self, msg):
        pid = str(msg.get('id', msg.get('parameter', ''))).rsplit('/', 1)[-1]
        entry = self.ParameterIds.get(pid)
        if entry:
            path, parameter = entry
            parameter['value'] = msg.get('value')
            self._applyOptimistic(path, normalized(parameter))
        registry = self.ownerComp.FxRegistry
        if registry:
            for effect in registry.Registry.values():
                if str(effect.get('opacity_id')) == pid:
                    value = normalized(msg)
                    if msg.get('type') == 'parameter_get' and effect.get('_pending_until', 0) > time.time() and value != effect['opacity_value']:
                        continue
                    effect['opacity_value'] = value
                    effect['_padOn'] = effect['opacity_value'] > 0.002
                elif str(effect.get('bypassed_id')) == pid:
                    value = bool(msg.get('value'))
                    if msg.get('type') == 'parameter_get' and effect.get('_pending_until', 0) > time.time() and value != effect['bypassed_value']:
                        continue
                    effect['bypassed_value'] = value

    def CurrentOpacity(self, target, slot):
        registry = self.ownerComp.FxRegistry
        entry = registry.Registry.get('%s:%d' % (target, slot)) if registry else None
        return entry.get('opacity_value') if entry else None

    def LayerIdsOK(self):
        return bool(self.Composition and len(self.Bindings) == 7 and not self.BindingError)

    def Fresh(self):
        return bool(self.LastReceived and time.monotonic() - self.LastReceived < 10.0)
